import{_ as o,o as t,c as a,a4 as d}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse(`{"title":"Exposer l'API en entier","description":"Extrait de deploy/LISEZMOI.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"Exposer l'API en entier","description":"Extrait de deploy/LISEZMOI.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"documentation/referent/exposer-l-api-en-entier.md","filePath":"documentation/referent/exposer-l-api-en-entier.md"}`),i={name:"documentation/referent/exposer-l-api-en-entier.md"};function s(n,e,r,c,l,p){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="exposer-lapi-en-entier" tabindex="-1">Exposer l&#39;API en entier <a class="header-anchor" href="#exposer-lapi-en-entier" aria-label="Permalink to &quot;Exposer l&#39;API en entier {#exposer-lapi-en-entier}&quot;">​</a></h1><p>Réservé au profil « Sur mesure (headless) » (aucune extension installée, un front tiers consomme l&#39;API) ou à l&#39;option d&#39;installation <code>--api-publique</code>. Renseignez <code>TEUTHIS_DOMAINE_API</code> dans <code>.env</code> (le DNS doit déjà pointer vers ce serveur), copiez <code>caddy/sites-disponibles/api.caddy</code> vers <code>caddy/sites-actifs/</code>, puis <code>docker compose up -d</code>. N&#39;activez pas ce gabarit « au cas où » : dans tous les autres profils, l&#39;API ne doit rester joignable que sous <code>cms.&lt;votre domaine&gt;/_api/</code>.</p><h2 id="plafonds-et-délais-de-caddy" tabindex="-1">Plafonds et délais de Caddy <a class="header-anchor" href="#plafonds-et-délais-de-caddy" aria-label="Permalink to &quot;Plafonds et délais de Caddy {#plafonds-et-délais-de-caddy}&quot;">​</a></h2><p>Les routes <strong>publiques</strong> de l&#39;API (<code>/api/v1/public/…</code>, sous <code>cms.&lt;votre domaine&gt;/_api/</code> comme sur <code>api.&lt;votre domaine&gt;</code>) et tout le site public (<code>www.&lt;votre domaine&gt;</code>, qui relaie les formulaires) n&#39;acceptent pas de corps de plus de <strong>11 Mo</strong> (<code>TEUTHIS_CADDY_CORPS_PUBLIC_MAX_MO</code>, juste au-dessus de la pièce jointe publique de 10 Mo, <code>PUBLIC_UPLOAD_MAX_MB</code>), et une connexion publique inactive plus de 3 minutes est coupée. Le back-office, qui dépose des vidéos, garde <strong>550 Mo</strong> (<code>TEUTHIS_CADDY_CORPS_MAX_MO</code>) et 10 minutes. Si vous relevez l&#39;un des plafonds de l&#39;API dans <code>.env</code>, relevez le plafond Caddy correspondant d&#39;autant.</p><h2 id="documentation-interactive-de-lapi" tabindex="-1">Documentation interactive de l&#39;API <a class="header-anchor" href="#documentation-interactive-de-lapi" aria-label="Permalink to &quot;Documentation interactive de l&#39;API {#documentation-interactive-de-lapi}&quot;">​</a></h2><p><code>/docs</code> et <code>/openapi.json</code> sont <strong>fermés par défaut</strong> (<code>API_DOCS_ENABLED=false</code>, audit du 26/09/2026, EXP-13). Elles ne sont servies que par <code>api.&lt;votre domaine&gt;</code> (le gabarit <code>cms.caddy</code> ne relaie que les routes publiques). L&#39;intégrateur qui développe le site public contre cette API peut en avoir besoin : ajoutez <code>API_DOCS_ENABLED=true</code> dans <code>.env</code>, puis <code>docker compose up -d cms-api cms-scheduler</code>. La description liste toutes les routes et leurs paramètres : ne l&#39;ouvrez pas sans raison, et refermez-la (retirez la ligne, puis relancez la même commande) quand le travail est fini.</p>',6)])])}const _=o(i,[["render",s]]);export{m as __pageData,_ as default};
